<?php
declare(strict_types=1);$config=require __DIR__.'/../config/database.php';$pdo=new PDO("mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$periodo=(string)($_GET['periodo']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$periodo))$periodo=date('Y-m');$d=$periodo.'-01';$h=(new DateTimeImmutable($d))->modify('last day of this month')->format('Y-m-d');$st=$pdo->prepare("SELECT COALESCE(SUM(importe),0) total,COALESCE(SUM(CASE WHEN tipo='MENSUALIDAD' THEN importe ELSE 0 END),0) mens,COALESCE(SUM(CASE WHEN tipo='INSCRIPCION' THEN importe ELSE 0 END),0) ins,COALESCE(SUM(CASE WHEN tipo='INTENSIVO' THEN importe ELSE 0 END),0) ints FROM pagos WHERE estado='VALIDO' AND DATE(fecha) BETWEEN :d AND :h");$st->execute([':d'=>$d,':h'=>$h]);$r=$st->fetch();$mens=(float)$r['mens'];$ints=(float)$r['ints'];$ins=(float)$r['ins'];$hache=$mens*.5+$ints*.5;$proa=$hache+$ins;$min=(float)($pdo->query("SELECT valor FROM configuracion WHERE clave='minimo_proa_mensual' LIMIT 1")->fetchColumn()?:28000);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="hache-liquidacion-'.$periodo.'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['Periodo',$periodo]);fputcsv($out,['Concepto','Total','Hache','PROA']);fputcsv($out,['Mensualidades',$mens,$mens*.5,$mens*.5]);fputcsv($out,['Cursos intensivos',$ints,$ints*.5,$ints*.5]);fputcsv($out,['Inscripciones',$ins,0,$ins]);fputcsv($out,['TOTAL',(float)$r['total'],$hache,$proa]);fputcsv($out,['Mínimo PROA',$min,'',$proa>=$min?'ALCANZADO':'PENDIENTE']);fclose($out);